1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HexFormat;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Deterministic household id for an owner: the first 12 upper-case hex characters of
12	 * SHA-256 over {@code normalizedLastName + '|' + postcode}. Owners with the same last
13	 * name (compared case-insensitively with collapsed whitespace) and postcode therefore
14	 * share it automatically, without any stored link.
15	 */
16	final class HouseholdId {
17	
18	    private HouseholdId() {
19	    }
20	
21	    static String of(Owner owner) {
22	        String lastName = owner.getLastName() == null ? ""
23	                : owner.getLastName().trim().replaceAll("\\s+", " ").toLowerCase();
24	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
25	        try {
26	            byte[] digest = MessageDigest.getInstance("SHA-256")
27	                    .digest((lastName + '|' + postcode).getBytes(StandardCharsets.UTF_8));
28	            return HexFormat.of().formatHex(digest).substring(0, 12).toUpperCase();
29	        } catch (NoSuchAlgorithmException ex) {
30	            throw new IllegalStateException(ex);
31	        }
32	    }
33	}
