13	 * city with no known region accepts any 4-digit postcode, and an absent postcode is left
14	 * untouched. Rejects an out-of-range or malformed value with a 400.
15	 */
16	public class EnsureOwnerPostcode {
17	
18	    private static final Map<String, int[]> REGION_RANGES = Map.of(
19	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
20	
21	    public void service(@Val Owner owner) throws InvalidPostcodeException {
22	        String postcode = owner.getPostcode();
23	        if (postcode == null) {
24	            return;
25	        }
26	        if (!postcode.matches("\\d{4}")) {
27	            throw new InvalidPostcodeException("Postcode must be 4 digits");
28	        }
29	        int[] range = REGION_RANGES.get(Locality.of(owner.getCity()));
30	        if (range != null) {
31	            int value = Integer.parseInt(postcode);
32	            if (value < range[0] || value > range[1]) {
33	                throw new InvalidPostcodeException("Postcode is not valid for the owner's city");
34	            }
35	        }
36	    }
37	}
