7	
8	    private static final Map<String, String> CITY_REGION =
9	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
10	
11	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
12	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
13	
14	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
15	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
16	
17	    private Locality() {
18	    }
19	
20	    /** The canonical region for {@code city}, or "UNKNOWN" when it is not in the table. */
21	    public static String of(String city) {
22	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
23	    }
24	
25	    /** Region by postcode range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling
26	     * back to the city table when the postcode is absent or in no known range. */
27	    public static String of(String city, String postcode) {
28	        if (postcode != null && postcode.matches("\\d{4}")) {
29	            int value = Integer.parseInt(postcode);
30	            for (Map.Entry<String, int[]> region : REGION_POSTCODES.entrySet()) {
31	                int[] range = region.getValue();
32	                if (value >= range[0] && value <= range[1]) {
33	                    return region.getKey();
34	                }
35	            }
36	        }
37	        return of(city);
38	    }
