11	/**
12	 * On create, assigns the owner's deterministic {@link HouseholdId} (derived from last name and
13	 * postcode) and rejects the owner when an existing owner already shares that household. Setting
14	 * {@code sharesHousehold=true} only bypasses this rejection, declaring the owner a household
15	 * member; the id is assigned either way.
16	 */
17	public class EnsureUniqueOwnerHousehold {
18	
19	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws DuplicateHouseholdException {
21	        String householdId = HouseholdId.of(owner);
22	        owner.setHouseholdId(householdId);
23	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
24	            return;
25	        }
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (!Objects.equals(existing.getId(), owner.getId())
28	                    && householdId.equals(existing.getHouseholdId())) {
29	                throw new DuplicateHouseholdException(
30	                        "Another owner already shares this last name and postcode");
31	            }
32	        }
33	    }
34	}
